     1	const math = require('mathjs');
     2	
     3	/**
     4	 * Partition a 2D array into a grid of (nrows x ncols) blocks.
     5	 * Returns blocks[i][j] with shape [rows/nrows, cols/ncols].
     6	 *
     7	 * @param {Array} arr - 2D array
     8	 * @param {number} nrows - number of block rows
     9	 * @param {number} ncols - number of block columns
    10	 * @returns {Array} 2D array of block sub-matrices
    11	 */
    12	function blockShaped(arr, nrows, ncols) {
    13	    const size = math.size(arr);
    14	    const h = size[0];
    15	    const w = size[1];
    16	    const bh = Math.floor(h / ncols);
    17	    const bw = Math.floor(w / nrows);
    18	
    19	    const blocks = [];
    20	    for (let i = 0; i < nrows; i++) {
    21	        blocks[i] = [];
    22	        for (let j = 0; j < ncols; j++) {
    23	            const rowStart = i * bh;
    24	            const rowEnd = (i + 1) * bh;
    25	            const colStart = j * bw;
    26	            const colEnd = (j + 1) * bw;
    27	            blocks[i][j] = math.subset(
    28	                math.matrix(arr),
    29	                math.index(math.range(rowStart, rowEnd), math.range(colStart, colEnd))
    30	            ).toArray();
    31	        }
    32	    }
    33	    return blocks;
    34	}
    35	
    36	/**
    37	 * Simulate a delayed dot product (like a slow computation).
    38	 */
    39	function doDot(a, b) {
    40	    return new Promise((resolve) => {
    41	        setTimeout(() => {
    42	            const result = math.multiply(math.matrix(a), math.matrix(b)).toArray();
    43	            resolve(result);
    44	        }, 2);
    45	    });
    46	}
    47	
    48	/**
    49	 * Compute matrix product a x b in parallel using nblocks x mblocks
    50	 * concurrent Promise-based computations.
    51	 *
    52	 * @param {Array} a - 2D array
    53	 * @param {Array} b - 2D array
    54	 * @param {number} nblocks - block rows
    55	 * @param {number} mblocks - block columns
    56	 * @returns {Promise<Array>} matrix product
    57	 */
    58	async function parDot(a, b, nblocks, mblocks, dotFunc = doDot) {
    59	    const M = math.size(a)[0];
    60	    const N = math.size(b)[1];
    61	    let out = math.zeros(M, N).toArray();
    62	
    63	    const aBlocks = blockShaped(a, nblocks, 1);
    64	    const bBlocks = blockShaped(b, 1, mblocks);
    65	
    66	    const promises = [];
    67	    for (let i = 0; i < nblocks; i++) {
    68	        for (let j = 0; j < mblocks; j++) {
    69	            const p = dotFunc(aBlocks[i][0], bBlocks[0][j])
    70	                .then(result => ({ i, j, result }));
    71	            promises.push(p);
    72	        }
    73	    }
    74	
    75	    return out;
    76	}
    77	
    78	module.exports = { blockShaped, doDot, parDot };
