     3	/**
     4	 * Partition a 2D array into a grid of (nrows x ncols) blocks.
     5	 * Returns blocks[i][j] with shape [rows/nrows, cols/ncols].
     6	 *
     7	 * @param {Array} arr - 2D array
     8	 * @param {number} nrows - number of block rows
     9	 * @param {number} ncols - number of block columns
    10	 * @returns {Array} 2D array of block sub-matrices
    11	 */
    12	function blockShaped(arr, nrows, ncols) {
    13	    const size = math.size(arr);
    14	    const h = size[0];
    15	    const w = size[1];
    16	    const bh = Math.floor(h / ncols);
    17	    const bw = Math.floor(w / nrows);
    18	
    19	    const blocks = [];
    20	    for (let i = 0; i < nrows; i++) {
    21	        blocks[i] = [];
    22	        for (let j = 0; j < ncols; j++) {
    23	            const rowStart = i * bh;
    24	            const rowEnd = (i + 1) * bh;
    25	            const colStart = j * bw;
    26	            const colEnd = (j + 1) * bw;
    27	            blocks[i][j] = math.subset(
    28	                math.matrix(arr),
    29	                math.index(math.range(rowStart, rowEnd), math.range(colStart, colEnd))
    30	            ).toArray();
    31	        }
    32	    }
